int kvm_create_vcpu(struct kvm *kvm, u32 id) {
    int ret;
    struct kvm_vcpu *vcpu;

    if (id >= KVM_MAX_VCPUS)
        return -EINVAL;

    if (kvm->online_vcpus >= KVM_MAX_VCPUS)
        return -ENOSPC;

    if (kvm->vcpus[id])
        return -EEXIST;

    vcpu = kzalloc(sizeof(struct kvm_vcpu), GFP_KERNEL);
    if (!vcpu)
        return -ENOMEM;

    vcpu->kvm = kvm;
    vcpu->vcpu_id = id;

    ret = kvm_setup_vcpu(vcpu);
    if (ret < 0)
        goto free_vcpu;

    ret = init_preemption_notifier(&vcpu->preempt_notifier, vcpu);
    if (ret < 0)
        goto cleanup_vcpu;

    kvm->vcpus[id] = vcpu;
    kvm->online_vcpus++;

    kvm_arch_post_vcpu_creation(vcpu);

    return 0;

cleanup_vcpu:
    kvm_cleanup_vcpu(vcpu);
free_vcpu:
    kfree(vcpu);
    return ret;
}

int kvm_vcpu_create(struct kvm *kvm, u32 id)
{
	int ret;
	struct kvm_vcpu *vcpu;

	if (id >= KVM_MAX_VCPUS)
		return -EINVAL;

	vcpu = kzalloc(sizeof(struct kvm_vcpu), GFP_KERNEL);
	if (!vcpu)
		return -ENOMEM;

	vcpu->kvm = kvm;
	vcpu->vcpu_id = id;

	ret = kvm_arch_vcpu_create(vcpu);
	if (ret)
		goto free_vcpu;

	ret = kvm_init_vcpu(vcpu);
	if (ret)
		goto arch_cleanup;

	if (atomic_read(&kvm->online_vcpus) >= KVM_MAX_VCPUS) {
		ret = -EINVAL;
		goto arch_cleanup;
	}

	mutex_lock(&kvm->lock);
	if (kvm->vcpus[id]) {
		ret = -EEXIST;
		goto unlock;
	}
	kvm->vcpus[id] = vcpu;
	mutex_unlock(&kvm->lock);

	atomic_inc(&kvm->online_vcpus);
	kvm_arch_vcpu_postcreate(vcpu);

	return 0;

unlock:
	mutex_unlock(&kvm->lock);
arch_cleanup:
	kvm_arch_vcpu_destroy(vcpu);
free_vcpu:
	kfree(vcpu);
	return ret;
}

int kvm_vcpu_create(struct kvm *kvm, u32 id) {
    int ret;
    struct kvm_vcpu *vcpu;

    if (id >= KVM_MAX_VCPUS)
        return -EINVAL;

    vcpu = kvm_arch_vcpu_create(kvm, id);
    if (IS_ERR(vcpu))
        return PTR_ERR(vcpu);

    ret = kvm_vcpu_init(vcpu);
    if (ret) {
        kvm_arch_vcpu_free(vcpu);
        return ret;
    }

    spin_lock(&kvm->lock);
    if (kvm->online_vcpus >= kvm->max_vcpus) {
        spin_unlock(&kvm->lock);
        kvm_vcpu_uninit(vcpu);
        kvm_arch_vcpu_free(vcpu);
        return -EINVAL;
    }

    if (id < KVM_MAX_VCPUS && kvm->vcpus[id]) {
        spin_unlock(&kvm->lock);
        kvm_vcpu_uninit(vcpu);
        kvm_arch_vcpu_free(vcpu);
        return -EEXIST;
    }

    kvm->vcpus[id] = vcpu;
    kvm->online_vcpus++;
    spin_unlock(&kvm->lock);

    kvm_register_vcpu(vcpu);

    kvm_arch_post_create_vcpu(vcpu);

    return 0;
}

int kvm_vcpu_create(struct kvm *kvm, u32 id)
{
	int ret;
	struct kvm_vcpu *vcpu;

	if (id >= KVM_MAX_VCPUS)
		return -EINVAL;

	if (kvm->online_vcpus >= KVM_MAX_VCPUS)
		return -EINVAL;

	vcpu = kmem_cache_zalloc(kvm_vcpu_cache, GFP_KERNEL);
	if (!vcpu)
		return -ENOMEM;

	vcpu->kvm = kvm;
	vcpu->vcpu_id = id;

	ret = kvm_vcpu_init(vcpu);
	if (ret < 0)
		goto free_vcpu;

	ret = kvm_create_preemption_notifier(vcpu);
	if (ret < 0)
		goto deinit_vcpu;

	if (test_bit(id, kvm->vcpu_bitmap)) {
		ret = -EEXIST;
		goto destroy_preemption_notifier;
	}

	set_bit(id, kvm->vcpu_bitmap);
	kvm->online_vcpus++;

	kvm_register_vcpu(vcpu);

	kvm_arch_post_vcpu_creation(vcpu);

	return 0;

destroy_preemption_notifier:
	kvm_destroy_preemption_notifier(vcpu);
deinit_vcpu:
	kvm_vcpu_deinit(vcpu);
free_vcpu:
	kmem_cache_free(kvm_vcpu_cache, vcpu);
	return ret;
}

int kvm_vm_create_vcpu(struct kvm *kvm, u32 id) {
    int r;
    struct kvm_vcpu *vcpu;

    if (id >= KVM_MAX_VCPUS)
        return -EINVAL;

    if (kvm->online_vcpus >= KVM_MAX_VCPUS)
        return -ENOSPC;

    vcpu = kzalloc(sizeof(struct kvm_vcpu), GFP_KERNEL);
    if (!vcpu)
        return -ENOMEM;

    r = kvm_vcpu_setup(vcpu, kvm, id);
    if (r)
        goto free_vcpu;

    r = setup_vcpu_preempt_notifier(vcpu);
    if (r)
        goto cleanup_vcpu;

    if (id < kvm->online_vcpus) {
        r = -EEXIST;
        goto cleanup_notifier;
    }

    kvm->vcpu_list[id] = vcpu;
    kvm->online_vcpus++;

    r = kvm_arch_post_create_vcpu(vcpu);
    if (r)
        goto cleanup_notifier;

    return 0;

cleanup_notifier:
    teardown_vcpu_preempt_notifier(vcpu);
cleanup_vcpu:
    kvm_vcpu_destroy(vcpu);
free_vcpu:
    kfree(vcpu);
    return r;
}
